import {initializeAppearance} from './appearance.mjs';
let preferenceStorage;try{preferenceStorage=localStorage;}catch{}
initializeAppearance(document,preferenceStorage);
const $=id=>document.getElementById(id);
const worker=new Worker(new URL('./search-worker.mjs',import.meta.url),{type:'module'});
let serial=0,ready=false,meta,facets,area='',page=0,suggestions=[],active=-1,searchId=0,suggestId=0,timer;
const byId=new Map();
function node(tag,text,className){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;}
function notify(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').hidden=true,6000);}
function options(){return {query:$('search').value,area,subject:$('subject').value,series:$('series').value,from:$('from').value,to:$('to').value,sort:$('sort').value,page,pageSize:20};}
function validFilters(){const from=$('from').value,to=$('to').value;const valid=x=>!x||/^\d{4}$/.test(x)&&Number(x)>=1800&&Number(x)<=2100;const okay=valid(from)&&valid(to)&&(!from||!to||Number(from)<=Number(to));$('filter-error').hidden=okay;$('filter-error').textContent=okay?'':'Use years from 1800 to 2100. The “From” year must not be later than “To”.';return okay;}
function closeSuggestions(){suggestions=[];active=-1;$('suggestions').hidden=true;$('search').setAttribute('aria-expanded','false');$('search').removeAttribute('aria-activedescendant');}
function runSearch(reset=true){if(!ready||!validFilters())return;if(reset)page=0;closeSuggestions();$('results').setAttribute('aria-busy','true');searchId=++serial;worker.postMessage({id:searchId,action:'search',options:options()});}
function populateSelect(id,values,first){const select=$(id),previous=select.value;select.replaceChildren(new Option(first,''));for(const [label,count]of values)select.append(new Option(`${label} (${count.toLocaleString()})`,label));if(previous&&!values.some(([label])=>label===previous))select.append(new Option(previous+' (not in refreshed catalog)',previous));select.value=previous;select.disabled=false;}
function selectArea(next){area=next;for(const button of $('areas').children)button.setAttribute('aria-pressed',String(button.dataset.area===area));$('selection-label').textContent=area||'All subject areas';$('grc-guides').hidden=area!=='Governance, Risk & Compliance';runSearch();}
function showAreas(){const all=meta.indexedRecords;const values=[['',all],...facets.areas];$('areas').replaceChildren();for(const [name,count]of values){const button=node('button',undefined,'area-button');button.type='button';button.dataset.area=name;button.setAttribute('aria-pressed',String(name===area));button.append(node('span',name||'All publications'),node('span',count.toLocaleString()));button.addEventListener('click',()=>selectArea(name));$('areas').append(button);}}
function render(result){byId.clear();$('results').replaceChildren();$('results').setAttribute('aria-busy','false');$('result-count').textContent=`${result.total.toLocaleString()} ${result.total===1?'publication':'publications'} found`;$('related').hidden=!result.related;$('results-heading').textContent=$('search').value?`Results for “${$('search').value}”`:'Publications';
  if(!result.items.length){const empty=node('div',undefined,'empty');empty.append(node('h3','Let’s try a broader search.'),node('p','Try a shorter word, a publication number, or reset your filters. No results does not mean NIST has no guidance on this topic.'));const button=node('button','Reset search and filters','quiet');button.onclick=reset;empty.append(button);$('results').append(empty);}
  for(const r of result.items){byId.set(r.id,r);const card=node('article',undefined,'publication');card.dataset.id=r.id;const top=node('div',undefined,'publication-top');top.append(node('span',r.series,'series-tag'),node('span',r.year??'Year not cataloged'));const title=node('h3');const titleLink=node('a',r.title);titleLink.href=r.url;titleLink.target='_blank';titleLink.rel='noopener noreferrer';title.append(titleLink);card.append(top,title);
    if(r.doi)card.append(node('p',r.doi.replace(/^10\.6028\//i,'').replaceAll('.',' '),'pub-id'));
    card.append(node('p',r.abstract?r.abstract.slice(0,360)+(r.abstract.length>360?'…':''):'No abstract supplied in this catalog record. Open the original publication for its full scope.','abstract'));
    const tags=node('div',undefined,'tags');for(const text of r.subjects.slice(0,3))tags.append(node('span',text,'tag'));if(!r.subjects.length)for(const text of r.areas.slice(0,2))tags.append(node('span',text+' · inferred area','tag'));card.append(tags);
    const bottom=node('div',undefined,'publication-bottom');bottom.append(node('span','NIST Research Library · Verify version at source'));const link=node('a','Open publication ↗','source-link');link.href=r.url;link.target='_blank';link.rel='noopener noreferrer';bottom.append(link);card.append(bottom);
    const details=node('details',undefined,'details');details.append(node('summary','Authors, subjects & catalog notes'));details.append(node('p','Authors: '+(r.authors.join('; ')||'Not supplied')),node('p','Catalog subjects: '+(r.subjects.join(' · ')||'Not supplied')),node('p','Inferred areas: '+r.areas.join(' · ')));for(const note of r.notes)details.append(node('p',note));if(r.abstract.length>360)details.append(node('p',r.abstract));card.append(details);$('results').append(card);
  }
  const pages=Math.max(1,Math.ceil(result.total/result.pageSize));$('page-label').textContent=`Page ${page+1} of ${pages.toLocaleString()}`;$('previous').disabled=page===0;$('next').disabled=page+1>=pages;document.body.dataset.ready='true';
}
function renderSuggestions(values){suggestions=values;active=-1;const list=$('suggestions');list.replaceChildren();if(!values.length){closeSuggestions();return;}values.forEach((s,i)=>{const li=node('li');li.id='suggestion-'+i;li.setAttribute('role','option');li.setAttribute('aria-selected','false');li.append(node('span',s.label,'suggest-label'),node('span',(s.type==='subject'?'SUBJECT · ':'PUBLICATION · ')+s.detail,'suggest-detail'));li.addEventListener('pointerdown',e=>e.preventDefault());li.addEventListener('click',()=>choose(i));list.append(li);});list.hidden=false;$('search').setAttribute('aria-expanded','true');}
function choose(i){const s=suggestions[i];if(!s)return;if(s.type==='subject'){$('subject').value=s.value;$('search').value='';}else{$('search').value=s.detail.includes('10.6028/')?s.detail:s.value;}$('clear-search').hidden=!$('search').value;runSearch();$('search').focus();}
function reset(){area='';page=0;for(const id of ['search','series','subject','from','to'])$(id).value='';$('sort').value='relevance';$('clear-search').hidden=true;selectArea('');$('search').focus();}
function openCoverage(){$('coverage').showModal();}
worker.onmessage=({data})=>{if(data.error){$('results').replaceChildren(node('div',data.error,'error'));$('results').setAttribute('aria-busy','false');$('result-count').textContent='Check needed';return;}if(data.action==='init'){meta=data.meta;facets=data.facets;ready=true;$('search').disabled=false;$('search-button').disabled=false;populateSelect('series',facets.series,'All series');populateSelect('subject',facets.subjects,'All catalog subjects');showAreas();$('catalog-count').textContent=meta.indexedRecords.toLocaleString()+' official catalog records';$('catalog-release').textContent='NIST release: '+meta.release+' · Metadata search';$('coverage-text').textContent=meta.coverage;$('coverage-details').replaceChildren();for(const [label,text]of [['Source release',meta.release+' · '+new Date(meta.releaseDate).toLocaleDateString()],['Imported',new Date(meta.importedAt).toLocaleString()],['Completeness',meta.indexedRecords.toLocaleString()+' indexed / '+meta.sourceRecords.toLocaleString()+' source records'],['Source integrity','Release size and SHA-256 verified'],['Subject classification',meta.subjectMethod]])$('coverage-details').append(node('dt',label),node('dd',text));const source=node('a','Open the official source release ↗');source.href=meta.sourceUrl;source.target='_blank';source.rel='noopener noreferrer';const sourceDetail=node('dd');sourceDetail.append(source);$('coverage-details').append(node('dt','Source'),sourceDetail);runSearch();}else if(data.action==='search'&&data.id===searchId)render(data.result);else if(data.action==='suggest'&&data.id===suggestId&&document.activeElement===$('search'))renderSuggestions(data.result);};
worker.onerror=()=>{$('results').replaceChildren(node('div','The search engine could not start. Reload the page or contact the owner.','error'));$('result-count').textContent='Search unavailable';};
$('search-form').addEventListener('submit',e=>{e.preventDefault();if(active>=0)choose(active);else runSearch();});
$('search').addEventListener('input',()=>{$('clear-search').hidden=!$('search').value;clearTimeout(timer);closeSuggestions();suggestId=++serial;if(!ready)return;timer=setTimeout(()=>{suggestId=++serial;worker.postMessage({id:suggestId,action:'suggest',query:$('search').value,filters:options()});runSearch();},180);});
$('search').addEventListener('keydown',e=>{if(e.key==='Escape'){closeSuggestions();return;}if(!suggestions.length)return;if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();active=e.key==='ArrowDown'?(active+1)%suggestions.length:(active-1+suggestions.length)%suggestions.length;for(let i=0;i<suggestions.length;i++)$('suggestion-'+i).setAttribute('aria-selected',String(i===active));$('search').setAttribute('aria-activedescendant','suggestion-'+active);$('suggestion-'+active).scrollIntoView({block:'nearest'});}else if(e.key==='Enter'&&active>=0){e.preventDefault();choose(active);}});
$('search').addEventListener('blur',()=>setTimeout(closeSuggestions,150));
$('clear-search').onclick=()=>{$('search').value='';$('clear-search').hidden=true;runSearch();$('search').focus();};
for(const button of document.querySelectorAll('[data-query]'))button.onclick=()=>{if(!ready)return;$('search').value=button.dataset.query;$('clear-search').hidden=false;runSearch();$('search').focus();};
for(const id of ['series','subject','from','to','sort'])$(id).addEventListener('change',()=>runSearch());
$('reset').onclick=reset;$('previous').onclick=()=>{page=Math.max(0,page-1);runSearch(false);$('results-heading').scrollIntoView({block:'start'});};$('next').onclick=()=>{page++;runSearch(false);$('results-heading').scrollIntoView({block:'start'});};
$('about').onclick=openCoverage;$('coverage-button').onclick=openCoverage;$('close-coverage').onclick=()=>$('coverage').close();
$('share').onclick=async()=>{if(['127.0.0.1','localhost'].includes(location.hostname)){notify('This preview is local to your computer. Share the published website link when it is ready.');return;}try{await navigator.clipboard.writeText(location.origin+location.pathname);notify('Link copied. Anyone with this public link can browse—no editing access.');}catch{notify('Copy the website address from your browser’s address bar to share it.');}};
worker.addEventListener('message',({data})=>{
  if(data.action==='init'&&!data.error){$('refresh').disabled=false;$('refresh').textContent='↻ Refresh catalog';$('catalog-release').textContent='NIST release: '+data.meta.release+' · '+(data.meta.deliveryChannel==='bundled fallback snapshot'?'Fallback snapshot—live catalog unavailable':'Monthly updates · Metadata search');if(data.meta.deliveryChannel==='bundled fallback snapshot')notify('The monthly published catalog is unavailable. Showing the bundled snapshot; check the source release date.');if(data.refreshed)notify('Latest published catalog reloaded. Your search and filters have been kept. Source release: '+data.meta.release+'.');}
  if(data.action==='refresh'&&data.error){$('refresh').disabled=false;$('refresh').textContent='↻ Refresh catalog';notify('Refresh failed. Your previously loaded catalog is still available.');runSearch(false);}
});
$('refresh').onclick=()=>{if($('refresh').disabled)return;$('refresh').disabled=true;$('refresh').textContent='Refreshing…';closeSuggestions();worker.postMessage({id:++serial,action:'refresh'});};
worker.postMessage({id:++serial,action:'init'});
